
const EskimiDef = {

    load: function(){

        return new Promise((resolve, reject)=>{

            var sizearr = document.querySelector('meta[name="ad.size"]')?.content.split(',');

            var pref = '';

            if(settings.responsive){

                pref = '%';
                settings.w = 100;
                settings.h = 100;
            }
            else{

                settings.w = parseInt(sizearr[0].split('=')[1]);
                settings.h = parseInt(sizearr[1].split('=')[1]);
                pref = 'px';
            }

            document.documentElement.style.setProperty('--ad-width', `${settings.w}${pref}`);
            document.documentElement.style.setProperty('--ad-height', `${settings.h}${pref}`);
            
            const divs_27 = document.getElementsByTagName('div');
            const canvases_27 = document.getElementsByTagName('canvas');
            const inputs_27 = document.getElementsByTagName('input');
            const svgs_27 = document.getElementsByTagName('svg');
            
            const obs_27 = [divs_27, canvases_27, inputs_27, svgs_27];

            var outDoc_27;
            var outWin_27;
            var outFrame_27;

            async function setWindow_27(){

                return new Promise((resolve, reject) => {

                    try {
                
                        var curWindow = window;
                        var myInterval = setInterval(() => {
                
                            if (curWindow.frameElement == null) {
                
                                outDoc_27 = curWindow.document;
                
                                outWin_27 = curWindow;
                                clearInterval(myInterval);
                
                                return resolve(outWin_27);
                
                            }
                            else {
                
                                outFrame_27 = curWindow.frameElement;
                            }
                
                            curWindow = curWindow.parent;
                
                        }, 10);
                
                    } catch (error) {
                
                        console.error(error);
                
                        return reject(error);
                    }
                });
            }

            function observerCall(entries, observer){

                entries.forEach( (entry) => {
        
                    if(entry.isIntersecting){
                        
                        // console.log('appear');
                        document.dispatchEvent(new CustomEvent('adVisible', {detail: true}));
                        adInView = true;
                    }
                    else{
        
                        // console.log('gone');
                        document.dispatchEvent(new CustomEvent('adHidden', {detail: false}));
                        adInView = false;
                    }
                });
            }

            function setObserver(){

                if(typeof(outFrame_27) === 'undefined'){
        
                    outFrame_27 = wrapper;
                }
        
                var observerOptions = {
        
                    root: outDoc_27,
                    rootMargin: '0px',
                    threshold: 0.1
                };
        
                observer = new IntersectionObserver(observerCall, observerOptions);
        
                observer.observe(outFrame_27);
        
            }
            
            async function loadFonts_27(){
            
                return new Promise((resolve, reject)=>{

                    var types = [];
            
                    settings.assets.forEach((el)=>{

                        types.push(el.type);
            
                        if(el.type === 'font'){
            
                            const font = new FontFace(el.fontName, `url(${assets_url + el.src}.${el.format})`);
                            
                            font.load().then(()=>{
                    
                                document.fonts.add(font);

                                return resolve(font);
                            });
                        }
                    });

                    if(!types.includes('font')){

                        return resolve(undefined);
                    }
                });
            }
            
            async function loadImages_27(){
            
                return new Promise((resolve, reject)=>{
            
                    var cnt = 0;
                    var length = 0;
            
                    var loadedImg = [];
                    
                    settings.assets.forEach((el)=>{
            
                        if(el.format === 'png' || el.format === 'jpg' && el.src !== ''){
            
                            var spl = el.src.split(' ');
                            var form = el.format;
                            var temparr = [];
            
                            spl.forEach((el)=>{
            
                                temparr.push(el.replace(/([.,#])/g, ''));
                            });
            
                            var cleanarr = temparr.filter((el) => {
                                
                                return !el.match(/([,$%^&*()+=@!:;]){1,10}/g) ? el : null;
                            });
            
                            // console.log(cleanarr, temparr);
                            
                            length += cleanarr.length;
            
                            cleanarr.forEach((el)=>{
            
                                var img = new Image();
                                // var img = document.createElement('img');

                                for(var key in divs_27){

                                    if(divs_27.hasOwnProperty(key)){

                                        if(divs_27[key].classList.contains(el) || divs_27[key].id === el){

                                            divs_27[key].style.backgroundImage = `url(${assets_url + el}.${form})`;
                                        }
                                    }
                                }
                                
                                img.src = `${assets_url + el}.${form}`;
                                img.dataset.att = el;
                                
                                settings.cors ? img.crossOrigin = 'anonymous' : null;
                                
                                img.addEventListener('load', (e)=>{
            
                                    cnt ++;
                                    
                                    loadedImg.push(img);
            
                                    // img = null;
                                    
                                    if(cnt == length){
                                        
                                        return resolve(loadedImg);
                                    }
                                });
                                
                            });
                        }
                    });
                });
            }
            
            function setOb_27(node, nr){
            
                var cln = '';
                var idn = '';
            
                var d = node[nr];
            
                var nms;
            
                if(d.hasAttribute('class')){
            
                    cln = d.className;
            
                    if(d.tagName === 'svg'){
            
                        cln = cln.baseVal;
                    }
            
                    nms = cln.split(' ');
                }
            
                if(d.hasAttribute('id')){
            
                    idn = d.id;
                }
            
                if(idn !== ''){
            
                    o[idn] = d;
            
                    return;
                }
            
                if(cln !== ''){
            
                    o[nms[0]] = d;
                }
            }
            
            async function setObjects_27(){
            
                return new Promise((resolve, reject) => {
            
                    obs_27.forEach((el)=>{
            
                        for (var i = 0; i < el.length; i++) {
            
                            setOb_27(el, i);
                        } 
                    });
            
                    return resolve();
                });
            }

            function respond_27(){

                return resolve();
            }
            
            loadImages_27().then((resolve)=>{
            
                b.images = {};
            
                resolve.forEach((el)=>{
            
                    b.images[el.dataset.att] = el;
                });
                
                loadFonts_27().then((resolve)=>{
            
                    b.font = resolve;
                    
                    setObjects_27().then(()=>{

                        respond_27();
                        
                        setWindow_27().then(()=>{

                            setObserver();

                            outDoc_27.addEventListener("visibilitychange", function(){

                                if(document.hidden){

                                    // console.log("Tab is hidden")
                                    document.dispatchEvent(new CustomEvent('adHidden', {detail: false}));
                                }
                                else{

                                    // console.log("Tab is visible")
                                    document.dispatchEvent(new CustomEvent('adVisible', {detail: true}));
                                }
                            });
                        });
                    });     
                });
            });
        });
    }
}

